-- CAPEX-RETIRE-FIXED-CURRENCY (bim-ootb prompts/CAPEX_DASHBOARD.md §5.68; owner 2026-11-13: *"the USD/BDT currency is if the user sets so"* ... retire the fixed rows: *"yes"*).
-- The Home goals that named a currency (USD / BDT pairs) are replaced by ONE goal per tile on the rows that read the login's currency (@$C_Currency_ID@, 202611131300_CAPEX-PAGE-MEASURES.sql):
-- same SeqNo, colour schema, chart, scope and role as the USD goal; the target is copied from the old goal in the client's accounting-schema currency (the currency $C_Currency_ID carries, Login.java:569), else 0.
-- The fixed rows are DEACTIVATED, not deleted (their history and the released packs stay intact). Idempotent: NOT EXISTS / AND IsActive='Y'.
-- Restore: UPDATE PA_Goal SET IsActive='Y' WHERE PA_Goal_ID IN (1000034,1000035,1000036,1000037,1000038,1000039,1000040,1000041,1000056,1000057); the same for PA_Measure / PA_MeasureCalc 1000000,1000014-1000020,1000035,1000036,1000040-1000042; DELETE FROM PA_Goal WHERE PA_Goal_ID BETWEEN 1000060 AND 1000064.
SELECT register_migration_script('202611131500_CAPEX-RETIRE-FIXED-CURRENCY.sql') FROM dual;

-- CAPEX Approved Budget
INSERT INTO PA_Goal (PA_Goal_ID,AD_Client_ID,AD_Org_ID,IsActive,Created,CreatedBy,Updated,UpdatedBy,SeqNo,Name,Description,AD_User_ID,PA_ColorSchema_ID,IsSummary,PA_GoalParent_ID,PA_Measure_ID,RelativeWeight,MeasureTarget,MeasureScope,MeasureDisplay,DateFrom,DateTo,MeasureActual,GoalPerformance,AD_Role_ID,ChartType,PA_Goal_UU)
SELECT 1000060,u.AD_Client_ID,u.AD_Org_ID,'Y',TO_TIMESTAMP('2026-11-13 15:00:00','YYYY-MM-DD HH24:MI:SS'),100,TO_TIMESTAMP('2026-11-13 15:00:00','YYYY-MM-DD HH24:MI:SS'),100,u.SeqNo,'CAPEX Approved Budget','CAPEX dashboard: approved budget in the login currency (replaces the USD and BDT goals)',u.AD_User_ID,u.PA_ColorSchema_ID,u.IsSummary,u.PA_GoalParent_ID,1000070,u.RelativeWeight,CASE WHEN (SELECT s.C_Currency_ID FROM AD_ClientInfo ci JOIN C_AcctSchema s ON s.C_AcctSchema_ID=ci.C_AcctSchema1_ID WHERE ci.AD_Client_ID=11)=100 THEN u.MeasureTarget WHEN (SELECT s.C_Currency_ID FROM AD_ClientInfo ci JOIN C_AcctSchema s ON s.C_AcctSchema_ID=ci.C_AcctSchema1_ID WHERE ci.AD_Client_ID=11)=(SELECT C_Currency_ID FROM C_Currency WHERE ISO_Code='BDT') THEN (SELECT b.MeasureTarget FROM PA_Goal b WHERE b.PA_Goal_ID=1000035) ELSE 0 END,u.MeasureScope,u.MeasureDisplay,u.DateFrom,u.DateTo,0,0,u.AD_Role_ID,u.ChartType,'5a0c3e1e-0b7d-4c1e-9f3a-cafe00030060' FROM PA_Goal u WHERE u.PA_Goal_ID=1000034 AND NOT EXISTS (SELECT 1 FROM PA_Goal WHERE PA_Goal_ID=1000060)
;
